    record item-verdict {
        id: string,
        feed: string,
        title: string,
        link: string,
        category: category,
        importance: importance,
        summary: string,
        kept: bool,
    }

    /// Selection — the items that made the digest, plus the id of every item
    /// considered, kept or not, so that all of them can be marked seen.
    record selection {
        entries: list<item-verdict>,
        considered: list<string>,
    }

    record digest {
        date: string,
        overview: string,
        entries: list<item-verdict>,
        considered: list<string>,
    }

    record published-digest {
        date: string,
        considered: list<string>,
        published: bool,
    }

    record run-report {
        date: string,
        recorded: u32,
    }
