/// Collect every distinct IBAN that passes the mod-97 check and has the length
/// its country code requires. The scan runs over the raw characters, so an IBAN
/// is found whether it is glued to a label ("IBAN:DE89...") or written in
/// groups of four separated by single spaces or hyphens.
fn find_ibans(text: &str) -> Vec<String> {
    let chars: Vec<char> = text.chars().collect();
    let mut found: Vec<String> = Vec::new();

    for i in 0..chars.len() {
        // Start only at a word boundary, on a letter (the country code).
        if i > 0 && chars[i - 1].is_ascii_alphanumeric() {
            continue;
        }
        if !chars[i].is_ascii_alphabetic() {
