}

/// Read an IBAN starting at `start`. Alphanumerics are taken; a single space or
/// hyphen is taken only when another alphanumeric follows it. The run ends at
/// the exact length the country code requires, where the checksum is tested.
fn iban_at(chars: &[char], start: usize) -> Option<String> {
    let mut acc = String::new();
    let mut expected: Option<usize> = None;
    let mut j = start;

    while j < chars.len() {
        let c = chars[j];
        if c.is_ascii_alphanumeric() {
            acc.push(c.to_ascii_uppercase());
        } else if c == ' ' || c == '-' {
            match chars.get(j + 1) {
                Some(n) if n.is_ascii_alphanumeric() => {}
                _ => break,
            }
        } else {
            break;
        }

        if acc.len() == 2 {
            expected = Some(country_length(&acc)?);
        }
        if let Some(len) = expected {
            if acc.len() == len {
                return if iban_checksum_ok(&acc) { Some(acc) } else { None };
            }
        }
        j += 1;
    }
    None
}

/// Total IBAN length for every country in the ISO 13616 IBAN registry. A
/// country not listed here is refused rather than guessed at.
fn country_length(cc: &str) -> Option<usize> {
    Some(match cc {
        "AD" => 24,
        "AE" => 23,
        "AL" => 28,
        "AT" => 20,
