fn iban_checksum_ok(iban: &str) -> bool {
    let b = iban.as_bytes();
    if b.len() < 15 || b.len() > 34 {
        return false;
    }
    if !(b[0].is_ascii_uppercase()
        && b[1].is_ascii_uppercase()
        && b[2].is_ascii_digit()
        && b[3].is_ascii_digit())
    {
        return false;
    }
    if !b.iter().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit()) {
        return false;
    }
    let mut rem: u32 = 0;
    for &c in b[4..].iter().chain(b[..4].iter()) {
        if c.is_ascii_digit() {
            rem = (rem * 10 + (c - b'0') as u32) % 97;
        } else {
            let v = (c - b'A') as u32 + 10;
            rem = (rem * 100 + v) % 97;
        }
    }
    rem == 1
}

/// Find the amount due. Only lines mentioning a total (or "amount due") are
/// considered. Anything other than exactly one distinct amount is refused.
fn find_total(text: &str) -> Result<f64, String> {
    let mut amounts: Vec<f64> = Vec::new();
    for line in text.lines() {
        let lower = line.to_lowercase();
        let is_total_line = (lower.contains("total")
            && !lower.contains("subtotal")
            && !lower.contains("sub-total"))
            || lower.contains("amount due");
        if !is_total_line {
            continue;
        }
        for tok in line.split_whitespace() {
            if let Some(v) = parse_amount(tok) {
                if !amounts.contains(&v) {
                    amounts.push(v);
                }
            }
        }
    }
    match amounts.as_slice() {
        [one] if one.is_finite() && *one > 0.0 => Ok(*one),
        [] => Err("no total due found in the bill".into()),
        _ => Err("bill does not state exactly one total; refusing to choose".into()),
    }
}

/// Parse an amount with exactly two decimal digits, e.g. "1,234.56" or "1.234,56".
fn parse_amount(tok: &str) -> Option<f64> {
    let t: String = tok
        .chars()
        .filter(|c| c.is_ascii_digit() || *c == '.' || *c == ',')
        .collect();
    let last = t.rfind(|c: char| c == '.' || c == ',')?;
    let frac = &t[last + 1..];
    if frac.len() != 2 || !frac.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let int_part: String = t[..last].chars().filter(|c| c.is_ascii_digit()).collect();
    if int_part.is_empty() {
        return None;
    }
    format!("{}.{}", int_part, frac).parse::<f64>().ok()
}

/// Find the due date (ISO YYYY-MM-DD) on a line mentioning "due". Anything
/// other than exactly one distinct date is refused.
fn find_due_date(text: &str) -> Result<String, String> {
    let mut dates: Vec<String> = Vec::new();
    for line in text.lines() {
        if !line.to_lowercase().contains("due") {
            continue;
        }
        for tok in line.split_whitespace() {
            let t = tok.trim_matches(|c: char| !c.is_ascii_alphanumeric() && c != '-');
            if is_iso_date(t) && !dates.iter().any(|d| d == t) {
                dates.push(t.to_string());
            }
        }
    }
    match dates.as_slice() {
        [one] => Ok(one.clone()),
        [] => Err("no due date found in the bill".into()),
        _ => Err("bill states more than one due date; refusing to choose".into()),
    }
}

fn is_iso_date(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    if !b
        .iter()
        .enumerate()
        .all(|(i, c)| i == 4 || i == 7 || c.is_ascii_digit())
    {
        return false;
    }
    let month: u32 = s[5..7].parse().unwrap_or(0);
    let day: u32 = s[8..10].parse().unwrap_or(0);
    (1..=12).contains(&month) && (1..=31).contains(&day)
}
```

