/// ISO 13616 mod-97 check on an unspaced, uppercase IBAN.
fn iban_valid(s: &str) -> bool {
    if s.len() < 15 || s.len() > 34 {
        return false;
    }
    if !s.chars().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit()) {
        return false;
    }
    let b = s.as_bytes();
    if !(b[0].is_ascii_uppercase()
        && b[1].is_ascii_uppercase()
        && b[2].is_ascii_digit()
        && b[3].is_ascii_digit())
    {
        return false;
    }
    let mut rem: u32 = 0;
    for c in s[4..].chars().chain(s[..4].chars()) {
        if let Some(d) = c.to_digit(10) {
            rem = (rem * 10 + d) % 97;
        } else {
            let v = c as u32 - 'A' as u32 + 10;
            rem = (rem * 100 + v) % 97;
        }
    }
    rem == 1
}

/// Finds every checksum-valid IBAN in the text, with spaces between groups allowed.
fn find_ibans(text: &str) -> Vec<String> {
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    let mut found: Vec<String> = Vec::new();

    for i in 0..n {
        if i > 0 && chars[i - 1].is_ascii_alphanumeric() {
            continue;
        }
        if i + 4 > n {
            break;
        }
        if !(chars[i].is_ascii_uppercase()
            && chars[i + 1].is_ascii_uppercase()
            && chars[i + 2].is_ascii_digit()
            && chars[i + 3].is_ascii_digit())
        {
            continue;
        }
        let cc: String = chars[i..i + 2].iter().collect();
        let Some(len) = iban_len(&cc) else {
            continue;
        };

        let mut stream = String::new();
        let mut j = i;
        while j < n {
            let c = chars[j];
            if c.is_ascii_uppercase() || c.is_ascii_digit() {
                stream.push(c);
            } else if c == ' '
                && j + 1 < n
                && (chars[j + 1].is_ascii_uppercase() || chars[j + 1].is_ascii_digit())
            {
                // single space inside an IBAN grouping: skip it
            } else {
                break;
            }
            j += 1;
        }

        if stream.len() < len {
            continue;
        }
        let cand = &stream[..len];
        if iban_valid(cand) && !found.iter().any(|f| f == cand) {
            found.push(cand.to_string());
        }
    }
    found
}

/// Parses one run of digits and separators. The last separator is a decimal point
/// or comma when exactly one or two digits follow it; otherwise separators are
/// thousands grouping.
fn parse_amount(run: &str) -> Option<f64> {
    if run.is_empty() || !run.chars().all(|c| c.is_ascii_digit() || c == '.' || c == ',') {
        return None;
    }
    let (int_part, frac) = match run.rfind(|c| c == '.' || c == ',') {
        Some(p) if (1..=2).contains(&(run.len() - p - 1)) => (&run[..p], &run[p + 1..]),
        _ => (run, ""),
    };
    if !frac.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let int_digits: String = int_part.chars().filter(|c| c.is_ascii_digit()).collect();
    if int_digits.is_empty() {
        return None;
    }
    let s = if frac.is_empty() {
        int_digits
    } else {
        format!("{int_digits}.{frac}")
    };
    s.parse::<f64>().ok().filter(|a| *a > 0.0)
}

fn amounts_in(line: &str) -> Vec<f64> {
    let mut out = Vec::new();
    let mut cur = String::new();
    for c in line.chars().chain(std::iter::once(' ')) {
        if c.is_ascii_digit() || c == '.' || c == ',' {
            cur.push(c);
        } else {
            if cur.chars().any(|d| d.is_ascii_digit()) {
                let trimmed = cur.trim_matches(|c| c == '.' || c == ',');
                if let Some(a) = parse_amount(trimmed) {
                    out.push(a);
                }
            }
            cur.clear();
        }
    }
    out
}

const DUE_WORDS: &[&str] = &["total due", "amount due", "amount payable", "balance due"];

/// 0 = an explicit "due" line, 1 = a plain total line, None = not a total line.
fn tier(lower: &str) -> Option<u8> {
    if DUE_WORDS.iter().any(|w| lower.contains(w)) {
        Some(0)
    } else if lower.contains("total")
        && !lower.contains("subtotal")
        && !lower.contains("vat")
        && !lower.contains("tax")
    {
        Some(1)
    } else {
        None
    }
}

fn find_total(text: &str) -> Result<f64, String> {
    let lines: Vec<(&str, String)> = text.lines().map(|l| (l, l.to_lowercase())).collect();
    for t in 0..=1u8 {
        let mut values: Vec<f64> = Vec::new();
        for (orig, lower) in &lines {
            if tier(lower) == Some(t) {
                values.extend(amounts_in(orig));
            }
        }
        if values.is_empty() {
            continue;
        }
        let mut cents: Vec<i64> = values.iter().map(|v| (v * 100.0).round() as i64).collect();
        cents.sort_unstable();
        cents.dedup();
        return match cents.as_slice() {
            [one] => Ok(*one as f64 / 100.0),
            _ => Err("bill shows more than one total due; refusing to choose".into()),
        };
    }
    Err("no total due found in bill".into())
}
