/// How an alphanumeric character relates to the one before it.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Gap {
    /// First alphanumeric in the text.
    Start,
    /// Directly adjacent to the previous alphanumeric.
    Glued,
    /// Separated from the previous alphanumeric only by spaces or hyphens.
    Sep,
    /// Separated by anything else (punctuation, a newline, a colon, ...).
    Break,
}

#[derive(Clone, Copy)]
struct Tok {
    c: char,
    start: usize,
    end: usize,
    gap: Gap,
}

/// Spaces (any horizontal whitespace, including non-breaking) and hyphens are
/// group separators inside a printed IBAN. Newlines are not.
fn is_sep(c: char) -> bool {
    c == '-' || (c.is_whitespace() && c != '\n' && c != '\r')
}

fn tokens(text: &str) -> Vec<Tok> {
    let mut out = Vec::new();
    let mut gap = Gap::Start;
    for (pos, c) in text.char_indices() {
        if c.is_ascii_alphanumeric() {
            out.push(Tok {
                c: c.to_ascii_uppercase(),
                start: pos,
                end: pos + c.len_utf8(),
                gap,
            });
            gap = Gap::Glued;
        } else if is_sep(c) {
            if gap == Gap::Glued {
                gap = Gap::Sep;
            }
        } else {
            gap = Gap::Break;
        }
    }
    out
}

/// Finds every checksum-valid IBAN in the text. Returns each occurrence with
/// its byte span in `text`, so the caller can mask it out.
fn find_ibans(text: &str) -> Vec<(String, usize, usize)> {
    let toks = tokens(text);
    let mut found = Vec::new();
    for k in 0..toks.len() {
        if k + 4 > toks.len() {
            break;
        }
        let head = &toks[k..k + 4];
        // Must start a token: not glued to a preceding letter or digit.
        if head[0].gap == Gap::Glued
            || !head[0].c.is_ascii_uppercase()
            || !head[1].c.is_ascii_uppercase()
            || !head[2].c.is_ascii_digit()
            || !head[3].c.is_ascii_digit()
        {
            continue;
        }
        let cc: String = [head[0].c, head[1].c].iter().collect();
        let Some(len) = iban_len(&cc) else {
            continue;
        };
        if k + len > toks.len() {
            continue;
        }
        let window = &toks[k..k + len];
        // Inside the IBAN, only separators may appear between characters.
        if window[1..].iter().any(|t| t.gap == Gap::Break) {
            continue;
        }
        // The IBAN must not be the prefix of a longer glued token.
        if k + len < toks.len() && toks[k + len].gap == Gap::Glued {
            continue;
        }
        let cand: String = window.iter().map(|t| t.c).collect();
        if iban_valid(&cand) {
            found.push((cand, window[0].start, window[len - 1].end));
        }
    }
    found
}

/// Replaces the given byte spans with spaces, keeping line structure.
fn mask(text: &str, spans: &[(usize, usize)]) -> String {
    text.char_indices()
        .map(|(pos, c)| {
            if spans.iter().any(|&(s, e)| pos >= s && pos < e) {
                ' '
            } else {
                c
            }
        })
        .collect()
}

/// Parses one run of digits and separators. The last separator is a decimal point
/// or comma when exactly one or two digits follow it; otherwise separators are
/// thousands grouping.
fn parse_amount(run: &str) -> Option<f64> {
    if run.is_empty() || !run.chars().all(|c| c.is_ascii_digit() || c == '.' || c == ',') {
        return None;
    }
    let (int_part, frac) = match run.rfind(|c| c == '.' || c == ',') {
        Some(p) if (1..=2).contains(&(run.len() - p - 1)) => (&run[..p], &run[p + 1..]),
        _ => (run, ""),
    };
    if !frac.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let int_digits: String = int_part.chars().filter(|c| c.is_ascii_digit()).collect();
    if int_digits.is_empty() {
        return None;
    }
    let s = if frac.is_empty() {
        int_digits
    } else {
        format!("{int_digits}.{frac}")
    };
    s.parse::<f64>().ok().filter(|a| *a > 0.0)
}

fn amounts_in(line: &str) -> Vec<f64> {
    let mut out = Vec::new();
    let mut cur = String::new();
    for c in line.chars().chain(std::iter::once(' ')) {
        if c.is_ascii_digit() || c == '.' || c == ',' {
            cur.push(c);
        } else {
            if cur.chars().any(|d| d.is_ascii_digit()) {
                let trimmed = cur.trim_matches(|c| c == '.' || c == ',');
                if let Some(a) = parse_amount(trimmed) {
                    out.push(a);
                }
            }
            cur.clear();
        }
    }
    out
}

const DUE_WORDS: &[&str] = &["total due", "amount due", "amount payable", "balance due"];

/// 0 = an explicit "due" line, 1 = a plain total line, None = not a total line.
fn tier(lower: &str) -> Option<u8> {
    if DUE_WORDS.iter().any(|w| lower.contains(w)) {
        Some(0)
    } else if lower.contains("total")
        && !lower.contains("subtotal")
        && !lower.contains("vat")
        && !lower.contains("tax")
    {
        Some(1)
    } else {
        None
    }
}

fn find_total(text: &str) -> Result<f64, String> {
    let lines: Vec<(&str, String)> = text.lines().map(|l| (l, l.to_lowercase())).collect();
    for t in 0..=1u8 {
        let mut values: Vec<f64> = Vec::new();
        for (orig, lower) in &lines {
            if tier(lower) == Some(t) {
                values.extend(amounts_in(orig));
            }
        }
        if values.is_empty() {
            continue;
        }
        let mut cents: Vec<i64> = values.iter().map(|v| (v * 100.0).round() as i64).collect();
        cents.sort_unstable();
        cents.dedup();
        return match cents.as_slice() {
            [one] => Ok(*one as f64 / 100.0),
            _ => Err("bill shows more than one total due; refusing to choose".into()),
        };
    }
    Err("no total due found in bill".into())
}
